class Solution {
  public int minimumTime(List<Integer> nums1, List<Integer> nums2, int x) {
    int n = nums1.size();
    Integer[] order = new Integer[n];
    long sum1 = 0, sum2 = 0;
    for (int i = 0; i < n; i++) {
      order[i] = i;
      sum1 += nums1.get(i);
      sum2 += nums2.get(i);
    }
    // reset the fastest-growing elements last: process in ascending order of growth
    Arrays.sort(order, (a, b) -> Integer.compare(nums2.get(a), nums2.get(b)));
    long[] saved = new long[n + 1]; // saved[j]: most we can remove using j resets
    for (int idx : order) {
      int a = nums1.get(idx), b = nums2.get(idx);
      for (int j = n; j >= 1; j--) saved[j] = Math.max(saved[j], saved[j - 1] + a + (long) b * j);
    }
    for (int t = 0; t <= n; t++) {
      if (sum1 + sum2 * t - saved[t] <= x) return t;
    }
    return -1;
  }
}
